"""UI simplification: ensure future autogenerated HTML stays plain and uncluttered."""
import os
import sys
from pathlib import Path

from lvimot.output.offline_map import _offline_html


def test_offline_map_is_minimal_and_preserves_scene_data():
    page = _offline_html({'static': [[1.0, 2.0, 3.0]], 'road': [[4.0, 5.0, 6.0]], 'carla': [[7.0, 8.0, 9.0]]}, {}, {})
    assert 'LVIMOT Offline 4D Map' in page
    assert 'id="view"' in page
    assert 'id="mode"' in page and 'id="time"' in page
    assert 'id="showVehicles"' in page
    assert 'id="showLVIMOT"' in page
    assert 'id="showCarla"' in page
    assert 'Object IDs and last status' not in page
    assert 'parked-candidate label' not in page
    assert 'measured object IDs' not in page
    assert 'sensor-estimated rolling map' not in page
    assert 'Drag to rotate' not in page
    assert '#9aa6b2' in page
    assert '#57b95f' in page
    assert '#7d6df2' in page
    assert '[[1.0,2.0,3.0]]' in page
    assert '[[4.0,5.0,6.0]]' in page
    assert '[[7.0,8.0,9.0]]' in page
    assert 'o.trajectory' in page


def test_live_map_overlay_text_removed():
    src = (Path(__file__).resolve().parent.parent / 'lvimot/output/live_gui.py').read_text(encoding='utf-8')
    for clutter in ('sensor-estimated rolling map', 'Drag to rotate | height = z',
                    'agreement checked when the run finishes',
                    'The CARLA spectator window is optional; camera sensors remain active.'):
        assert clutter not in src
    assert 'Validated baseline:' in src
    assert 'def _redraw_map_health' in src
